# SaleHop update: fix address geocoding failures + "use my current location"
# - Address lookup now retries a cleaned-up version of the address (drops
#   apartment/unit/suite info, which trips up building-level geocoders) and
#   falls back to the US Census Bureau's free geocoder when OpenStreetMap's
#   Nominatim comes back empty. This was the main cause of the ~30% of
#   addresses that wouldn't save -- Nominatim alone misses a real chunk of
#   valid US addresses; Census is purpose-built for US postal addresses and
#   catches most of what Nominatim misses. Same fallback applies to the
#   as-you-type address suggestions on the Post screen.
# - Adds a "Use my current location" button under the address field on the
#   Post screen. Uses the browser's own Geolocation API, then reverse-
#   geocodes those coordinates back into a street address the same way
#   picking a typed suggestion works today.
# - No new API keys or paid services -- both geocoders used are free.

if (-not (Test-Path "package.json")) {
    Write-Host "ERROR: package.json not found. Run this script from inside your salehop project folder." -ForegroundColor Red
    exit 1
}
if (-not (Test-Path ".git")) {
    Write-Host "ERROR: .git folder not found. Run this script from inside your salehop project folder." -ForegroundColor Red
    exit 1
}

[System.IO.Directory]::SetCurrentDirectory((Get-Location).Path)

$dir_georoute = "app/api/geocode"
